B.bir=new A.ag("\u0639\u0642\u062f \u0627\u0644\u062c\u0627\u0645\u0639\u0629","\u0627\u0644\u0637\u0631\u0641\u0627\u0646: \u0627\u0644\u062c\u0627\u0645\u0639\u0629 \u0623\u0648 \u0627\u0644\u062c\u0647\u0629 \u0627\u0644\u062a\u064a \u062a\u0645\u062b\u0644\u0647\u0627\u060c \u0648\u0645\u0646\u0635\u0651\u0629 \u0645\u0627\u064a \u0627\u0643\u0632\u0627\u0645\u0633. \u0646\u0634\u0631 \u0645\u062d\u062a\u0648\u0649 \u0628\u0627\u0633\u0645 \u0627\u0644\u062c\u0627\u0645\u0639\u0629 \u064a\u062d\u062a\u0627\u062c \u062a\u0641\u0648\u064a\u0636\u0627\u064b \u062e\u0637\u064a\u0627\u064b \u0645\u0646 \u0627\u0644\u062c\u0647\u0629. \u0646\u0633\u0628\u0629 \u0627\u0644\u0645\u0646\u0635\u0629 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a\u0629 20\u066a \u0645\u0627 \u0644\u0645 \u064a\u064f\u062a\u0641\u0642 \u0639\u0644\u0649 \u063a\u064a\u0631\u0647\u0627 \u0643\u062a\u0627\u0628\u0629. \u0627\u0644\u0635\u0631\u0641 \u0628\u0639\u062f \u0637\u0644\u0628 \u0633\u062d\u0628 \u0648\u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0625\u062f\u0627\u0631\u0629. \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0633\u0648\u0631\u064a \u0647\u0648 \u0627\u0644\u062d\u0627\u0643\u0645 \u0625\u0630\u0627 \u0627\u0644\u0639\u0642\u062f \u0627\u0644\u0648\u0631\u0642\u064a \u0645\u0627 \u0646\u0635 \u0639\u0644\u0649 \u063a\u064a\u0631\u0647.")
